def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    # Coordinate-compress heights for a Fenwick tree.
    values = sorted(set(a))
    rank = {value: i + 1 for i, value in enumerate(values)}
    tree = [0] * (len(values) + 1)

    def add(index: int, delta: int) -> None:
        while index < len(tree):
            tree[index] += delta
            index += index & -index

    def prefix_sum(index: int) -> int:
        total = 0
        while index:
            total += tree[index]
            index -= index & -index
        return total

    result = []
    window_size = 0

    for i, height in enumerate(a):
        r = rank[height]
        # Count prior window heights strictly greater than this height.
        result.append(window_size - prefix_sum(r))
        add(r, 1)
        window_size += 1

        if i >= k:
            add(rank[a[i - k]], -1)
            window_size -= 1

    return result
